using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 changed the discriminator property from "Discriminator" to "$type".
            // Revert to the EF 8 name so existing 500K documents remain readable
            // and direct SQL queries filtering on c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed the id format from "EntityName|<key>" to just "<key>".
            // Preserve the EF 8 format so existing documents are still found by key.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<ProductIdValueGenerator>();
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // Opt back into sync I/O if needed during migration (see CosmosQuery.cs).
        // Remove once all call sites are async.
    }
}

