using Microsoft.EntityFrameworkCore;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed.
            // EF Core 9 changed the JSON discriminator from "Discriminator" to "$type".
            // Pin to the old name so existing 500K documents and raw SQL
            // (c.Discriminator = 'Product') continue to work.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format changed.
            // EF Core 8 wrote id as "Product|123"; EF Core 9 writes just "123".
            // Map a shadow property that preserves the EF 8 format so point-reads
            // against existing documents still resolve.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .ValueGeneratedOnAdd();

            // BREAKING CHANGE 3 — HasIndex is no longer silently ignored.
            // Cosmos has no secondary-index support; the HasIndex(p => p.Sku)
            // call has been removed.  Use a composite index in the Cosmos
            // indexing policy instead.
        });
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; }
}

